        if (!isEmpty()) {

            if (this.head.value == value) {
                this.head = this.head.next;
                this.size--;
                return true;
            }

            Node prev = null;
            Node aux = head;

            while (aux != null && aux.value != value) {
                prev = aux;
                aux = aux.next;
            }

            if (aux == null) return false;
            else {
                prev.next = aux.next;
                this.size--;
                return true;
            }

        }

        return false;


